//
//  SparkleSelfUpdater.swift
//  Pearcleaner
//
//  Self-updater for the fork: Sparkle downloads and installs DMGs from the
//  alecuba16 fork appcast. The AlinFoundation Updater stays pointed at
//  alienator88/Pearcleaner for release notes only; it can never consume fork
//  releases (fork tags are fork-vX.Y.Z-bN-timestamp, its version compare is
//  a plain string compare, and it only downloads zip assets).
//

import SwiftUI
import Sparkle

// The feed points at the fork repo release appcast, regenerated by CI per
// build and signed with the SUPublicEDKey ed25519 key from Info.plist.
enum SparkleSelfUpdaterConfig {
    static let feedURL = "https://github.com/alecuba16/Pearcleaner/releases/latest/download/appcast.xml"
}

@MainActor
protocol SparkleSelfUpdaterBackend: AnyObject {
    var automaticallyChecksForUpdates: Bool { get set }
    var canCheckForUpdates: Bool { get }
    func start() throws
    func checkForUpdates()
}

// The Sparkle session starts here so the Check for Updates menu item works
// from launch. It only phones home when the opt-in automatic-checks toggle
// is on; with it off (default) Sparkle does nothing until the user asks.
@MainActor
final class SparkleSelfUpdater: ObservableObject {
    private let backend: any SparkleSelfUpdaterBackend

    @AppStorage("settings.updater.sparkleAutomaticChecks") var automaticallyChecksForUpdates: Bool = false {
        didSet {
            backend.automaticallyChecksForUpdates = automaticallyChecksForUpdates
        }
    }

    @Published private(set) var canCheckForUpdates = false

    init(backend: (any SparkleSelfUpdaterBackend)? = nil) {
        self.backend = backend ?? SparkleBackend.shared
        try? self.backend.start()
        // Sparkle keeps its own preference; ours wins so the Settings toggle
        // stays the single source of truth across launches
        self.backend.automaticallyChecksForUpdates = automaticallyChecksForUpdates
        canCheckForUpdates = self.backend.canCheckForUpdates
    }

    func checkForUpdates() {
        backend.checkForUpdates()
    }
}

@MainActor
private final class SparkleBackend: SparkleSelfUpdaterBackend {
    static let shared = SparkleBackend()

    private let controller: SPUStandardUpdaterController
    private let delegate = SelfUpdaterDelegate()
    private var started = false

    private init() {
        controller = SPUStandardUpdaterController(
            startingUpdater: false,
            updaterDelegate: delegate,
            userDriverDelegate: nil
        )
    }

    var automaticallyChecksForUpdates: Bool {
        get { controller.updater.automaticallyChecksForUpdates }
        set { controller.updater.automaticallyChecksForUpdates = newValue }
    }

    var canCheckForUpdates: Bool { controller.updater.canCheckForUpdates }

    func start() throws {
        guard !started else { return }
        started = true
        try controller.updater.start()
    }

    func checkForUpdates() { controller.checkForUpdates(nil) }
}

private final class SelfUpdaterDelegate: NSObject, SPUUpdaterDelegate {
    func updater(_ updater: SPUUpdater, feedURLStringFor allowedChannels: Set<String>) -> String? {
        SparkleSelfUpdaterConfig.feedURL
    }
}
